override public func viewDidAppear(_ animated: Bool) {
    // GlowGram mod Privacy Lens: Face ID gate for protected chats.
    if !self.exteraPrivacyLensAuthorized, let peerId = self.chatLocation.peerId, ExteraPrivacyLensControllerHooks.isChatProtected(peerId: peerId.toInt64()) {
        self.exteraPrivacyLensAuthorized = false
        self.view.isUserInteractionEnabled = false
        ExteraPrivacyLensControllerHooks.authorizeProtectedChat(completion: { [weak self] granted in
            guard let self else { return }
            self.view.isUserInteractionEnabled = true
            if granted {
                self.exteraPrivacyLensAuthorized = true
            } else {
                self.dismiss()
            }
        })
    }
